svg.script:
const svg = document.documentElement;
const searchBox = document.getElementById("searchBox");
const searchText = document.getElementById("searchText");
const empty = document.getElementById("empty");
const gameNodes = Array.from(document.querySelectorAll("#games > a"));

let query = "";
let editing = false;

function update() {
  const q = query.trim().toLowerCase();
  let visible = 0;
  gameNodes.forEach(a => {
    const name = (a.querySelector(".gameText")?.textContent || "").toLowerCase();
    const show = !q || name.includes(q);
    a.style.display = show ? "" : "none";
    if (show) visible++;
  });
  searchText.textContent = query ? "🔎 " + query : "🔎 Search the hub...";
  searchText.setAttribute("fill", query ? "#f2f5f7" : "#8995a3");
  empty.style.display = visible ? "none" : "";
}

searchBox.addEventListener("click", () => {
  editing = true;
  const value = window.prompt("Search the hub:", query);
  if (value !== null) query = value;
  editing = false;
  update();
});

// Keyboard search when the SVG document has focus.
window.addEventListener("keydown", e => {
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  if (e.key === "Escape") { query = ""; update(); return; }
  if (e.key === "Backspace") { query = query.slice(0,-1); update(); return; }
  if (e.key.length === 1 && !editing) { query += e.key; update(); }
});

update();
